-- Imagen temporal: foto de categoría (reemplazar desde /admin/productos)

BEGIN;

INSERT INTO categorias (nombre, slug, descripcion, activo)
SELECT v.nombre, v.slug, v.descripcion, TRUE
FROM (
  VALUES
    ('Nariz', 'nariz', 'Piercings para nariz: nostril, septum, clicker y más.'),
    ('Ombligo', 'ombligo', 'Piercings para ombligo: curved barbell, cadenas y colgantes.'),
    ('Ceja', 'ceja', 'Piercings para ceja: curved, straight y micro barbell.'),
    ('Labio', 'labio', 'Piercings para labio: labret, monroe, medusa y más.'),
    ('Industrial', 'industrial', 'Piercings industrial: barbells rectos y diseños statement.'),
    ('Lengua', 'lengua', 'Piercings para lengua: barbells, gemas y anodizado.'),
    ('Pesones', 'pesones', 'Piercings para pesones: barbell, aro y escudo.')
) AS v(nombre, slug, descripcion)
WHERE NOT EXISTS (SELECT 1 FROM categorias c WHERE c.slug = v.slug);

