INSERT INTO producto_categorias (producto_id, categoria_id)
SELECT p.id, c.id
FROM productos p
JOIN categorias c ON c.slug = CASE
  WHEN p.codigo LIKE 'OP-NAR-%' THEN 'nariz'
  WHEN p.codigo LIKE 'OP-OMB-%' THEN 'ombligo'
  WHEN p.codigo LIKE 'OP-CEJ-%' THEN 'ceja'
  WHEN p.codigo LIKE 'OP-LAB-%' THEN 'labio'
  WHEN p.codigo LIKE 'OP-IND-%' THEN 'industrial'
  WHEN p.codigo LIKE 'OP-LEN-%' THEN 'lengua'
  WHEN p.codigo LIKE 'OP-PES-%' THEN 'pesones'
END
WHERE p.codigo ~ '^OP-(NAR|OMB|CEJ|LAB|IND|LEN|PES)-'
  AND NOT EXISTS (
    SELECT 1 FROM producto_categorias pc
    WHERE pc.producto_id = p.id AND pc.categoria_id = c.id
  );

COMMIT;
